// FaultDescription returns the human-readable title for a fault code,
// or the code itself when no description is known.
func FaultDescription(code string) string {
	if d, ok := FaultTitle[code]; ok { return d }
	return code
}

// TagDescriptionOf returns the human-readable description for an alarm/tag code,
// or the code itself when no description is known.
func TagDescriptionOf(code string) string {
	if d, ok := TagDescription[code]; ok { return d }
	return code
}
